32	entity Sweep is
33	    Port ( CLK : in  STD_LOGIC;
34	           RESET : in  STD_LOGIC;
35				  NPOINTS : in STD_LOGIC_VECTOR (12 downto 0);
36	           CONFIG_ADDRESS : out  STD_LOGIC_VECTOR (12 downto 0);
37	           CONFIG_DATA : in  STD_LOGIC_VECTOR (95 downto 0);
38				  USER_NSAMPLES : in STD_LOGIC_VECTOR (12 downto 0);
39				  NSAMPLES : out STD_LOGIC_VECTOR (12 downto 0);
40				  SETTLING_TIME : in STD_LOGIC_VECTOR (19 downto 0);
41	           SAMPLING_BUSY : in STD_LOGIC;
42				  SAMPLING_DONE : in  STD_LOGIC;
43				  START_SAMPLING : out STD_LOGIC;
44				  BAND_SELECT : out STD_LOGIC;
45				  -- fixed part of source/LO registers
46	           MAX2871_DEF_4 : in  STD_LOGIC_VECTOR (31 downto 0);
47	           MAX2871_DEF_3 : in  STD_LOGIC_VECTOR (31 downto 0);
48	           MAX2871_DEF_1 : in  STD_LOGIC_VECTOR (31 downto 0);
49	           MAX2871_DEF_0 : in  STD_LOGIC_VECTOR (31 downto 0);
50				  -- assembled source/LO registers
51				  SOURCE_REG_4 : out  STD_LOGIC_VECTOR (31 downto 0);
52	           SOURCE_REG_3 : out  STD_LOGIC_VECTOR (31 downto 0);
53	           SOURCE_REG_1 : out  STD_LOGIC_VECTOR (31 downto 0);
54	           SOURCE_REG_0 : out  STD_LOGIC_VECTOR (31 downto 0);
55				  LO_REG_4 : out  STD_LOGIC_VECTOR (31 downto 0);
56	           LO_REG_3 : out  STD_LOGIC_VECTOR (31 downto 0);
57	           LO_REG_1 : out  STD_LOGIC_VECTOR (31 downto 0);
58	           LO_REG_0 : out  STD_LOGIC_VECTOR (31 downto 0);
59				  RELOAD_PLL_REGS : out STD_LOGIC;
60				  PLL_RELOAD_DONE : in STD_LOGIC;
61				  PLL_LOCKED : in STD_LOGIC;
62				  SWEEP_HALTED : out STD_LOGIC;
63				  SWEEP_RESUME : in STD_LOGIC;
64				  
65				  SYNC_ENABLED : in STD_LOGIC;
66				  SYNC_MASTER : in STD_LOGIC;
67				  TRIGGER_IN : in STD_LOGIC;
68				  TRIGGER_OUT : out STD_LOGIC;
69				  
70				  NEW_DATA : out STD_LOGIC;
71				  
72				  ATTENUATOR : out STD_LOGIC_VECTOR(6 downto 0);
73				  SOURCE_FILTER : out STD_LOGIC_VECTOR(1 downto 0);
74				  
75				  --SETTLING_TIME : in STD_LOGIC_VECTOR (15 downto 0);
76				  
77				  STAGES : in STD_LOGIC_VECTOR (2 downto 0);
78				  PORT1_STAGE : in STD_LOGIC_VECTOR (2 downto 0);
79				  PORT2_STAGE : in STD_LOGIC_VECTOR (2 downto 0);
80				  
81				  PORT1_ACTIVE : out STD_LOGIC;
82				  PORT2_ACTIVE : out STD_LOGIC;
83				  
84				  SOURCE_CE : out STD_LOGIC;
85				  
86				  -- Debug signals
87				  DEBUG_STATUS : out STD_LOGIC_VECTOR (10 downto 0);
88				  RESULT_INDEX : out STD_LOGIC_VECTOR (15 downto 0)
89				  );
90	end Sweep;
91	
92	architecture Behavioral of Sweep is
93		signal point_cnt : unsigned(12 downto 0);
94		type Point_states is (WaitInitialLow, TriggerSetup, SettingUp, Settling, WaitTriggerHigh, Exciting, WaitTriggerLow, SamplingDone, NextPoint, Done);
95		signal state : Point_states;
96		signal settling_cnt : unsigned(19 downto 0);
97		signal stage_cnt : unsigned (2 downto 0);
98		signal config_reg : std_logic_vector(95 downto 0);
99		signal source_active : std_logic;
100	begin
101		
102		CONFIG_ADDRESS <= std_logic_vector(point_cnt);
103		
104		-- assemble registers
105		-- source register 0: N divider and fractional division value
106		SOURCE_REG_0 <= MAX2871_DEF_0(31) & "000000000" & config_reg(93) & config_reg(5 downto 0) & config_reg(26 downto 15) & "000";
107		-- source register 1: Modulus value
108		SOURCE_REG_1 <= MAX2871_DEF_1(31 downto 15) & config_reg(38 downto 27) & "001";
109		-- source register 3: VCO selection
110		SOURCE_REG_3 <= config_reg(11 downto 6) & MAX2871_DEF_3(25 downto 3) & "011";
111		-- output power A from config, output B disabled
112		SOURCE_REG_4 <= MAX2871_DEF_4(31 downto 23) & config_reg(14 downto 12) & MAX2871_DEF_4(19 downto 9) & "000" & MAX2871_DEF_4(5) & config_reg(47 downto 46) & "100";
113		
114		-- LO register 0: N divider and fractional division value
115		LO_REG_0 <= MAX2871_DEF_0(31) & "000000000" & config_reg(94) & config_reg(54 downto 49) & config_reg(75 downto 64) & "000";
116		-- LO register 1: Modulus value
117		LO_REG_1 <= MAX2871_DEF_1(31 downto 15) & config_reg(87 downto 76) & "001";
118		-- LO register 3: VCO selection
119		LO_REG_3 <= config_reg(60 downto 55) & MAX2871_DEF_3(25 downto 3) & "011";
120		-- both outputs enabled at +5dbm
121		LO_REG_4 <= MAX2871_DEF_4(31 downto 23) & config_reg(63 downto 61) & MAX2871_DEF_4(19 downto 9) & "111111100";
122		
123		ATTENUATOR <= config_reg(45 downto 39);
124		SOURCE_FILTER <= config_reg(89 downto 88);
125		BAND_SELECT <= config_reg(48);
126		SOURCE_CE <= source_active;
127								
128		NSAMPLES <= USER_NSAMPLES when config_reg(92 downto 90) = "000" else
129						std_logic_vector(to_unsigned(6, 13)) when config_reg(92 downto 90) = "001" else
130						std_logic_vector(to_unsigned(19, 13)) when config_reg(92 downto 90) = "010" else
131						std_logic_vector(to_unsigned(57, 13)) when config_reg(92 downto 90) = "011" else
132						std_logic_vector(to_unsigned(190, 13)) when config_reg(92 downto 90) = "100" else
133						std_logic_vector(to_unsigned(571, 13)) when config_reg(92 downto 90) = "101" else
134						std_logic_vector(to_unsigned(1904, 13)) when config_reg(92 downto 90) = "110" else
135						std_logic_vector(to_unsigned(5712, 13));
136		
137		DEBUG_STATUS(10 downto 7) <= "0000" when state = TriggerSetup else
138												"0001" when state = SettingUp else
139												"0010" when state = Settling else
140												"0011" when state = WaitTriggerHigh else
141												"0100" when state = Exciting else
142												"0101" when state = WaitTriggerLow else 
143												"0110" when state = SamplingDone else
144												"0111" when state = NextPoint else
145												"1000" when state = Done else
146												"1001";
147		DEBUG_STATUS(6) <= PLL_RELOAD_DONE;
148		DEBUG_STATUS(5) <= PLL_RELOAD_DONE and PLL_LOCKED;
149		DEBUG_STATUS(4) <= SAMPLING_BUSY;
150		DEBUG_STATUS(3) <= TRIGGER_IN;
151		DEBUG_STATUS(2) <= source_active;
152		DEBUG_STATUS(1 downto 0) <= (others => '1');
153	
154		config_reg <= CONFIG_DATA;
155	
156		process(CLK, RESET)
157		begin
158			if rising_edge(CLK) then
159				if RESET = '1' then
160					point_cnt <= (others => '0');
161					stage_cnt <= (others => '0');
162					state <= WaitInitialLow;
163					START_SAMPLING <= '0';
164					RELOAD_PLL_REGS <= '0';
165					SWEEP_HALTED <= '0';
166					RESULT_INDEX <= (others => '1');
167					PORT1_ACTIVE <= '0';
168					PORT2_ACTIVE <= '0';
169					TRIGGER_OUT <= '0';
170					source_active <= '0';
171				else
172					case state is
173						when WaitInitialLow =>
174							TRIGGER_OUT <= '0';
175							if TRIGGER_IN = '0' or SYNC_ENABLED = '0' then
176								state <= TriggerSetup;
177							end if;
178						when TriggerSetup =>
179							RELOAD_PLL_REGS <= '1';
180							if PLL_RELOAD_DONE = '0' then
181								state <= SettingUp;
182							end if;
183						when SettingUp =>
184							-- highest bit in config_reg determines whether the sweep should be halted prior to sampling
185							SWEEP_HALTED <= config_reg(95);
186							RELOAD_PLL_REGS <= '0';
187							settling_cnt <= unsigned(SETTLING_TIME);
188							if PLL_RELOAD_DONE = '1' and PLL_LOCKED = '1' then
189								-- check if halted sweep is resumed
190								if config_reg(95) = '0' or SWEEP_RESUME = '1' then
191									SWEEP_HALTED <= '0';
192	   							state <= Settling;
193								end if;
194							end if;
195						when Settling =>
196							NEW_DATA <= '0';
197							source_active <= '0';
198							if std_logic_vector(stage_cnt) = PORT1_STAGE then
199								PORT1_ACTIVE <= '1';
200								source_active <= '1';
201							else
202								PORT1_ACTIVE <= '0';
203							end if;
204							if std_logic_vector(stage_cnt) = PORT2_STAGE then
205								PORT2_ACTIVE <= '1';
206								source_active <= '1';
207							else
208								PORT2_ACTIVE <= '0';
209							end if;
210							-- wait for settling time to elapse
211							if settling_cnt > 0 then
212								settling_cnt <= settling_cnt - 1;
213							else
214								-- need to wait for the trigger
215								state <= WaitTriggerHigh;
216								if SYNC_MASTER = '1' then
217									-- this device generates the stimulus signal, it needs start the trigger itself
218									TRIGGER_OUT <= '1';
219								end if;
220							end if;
221						when WaitTriggerHigh =>
222							if TRIGGER_IN = '1' or SYNC_ENABLED = '0' then 
223								TRIGGER_OUT <= SYNC_ENABLED; -- pass on trigger signal if enabled
224								START_SAMPLING <= '1';
225								if SAMPLING_BUSY = '1' then
226									state <= Exciting;
227								end if;
228							end if;
229						when Exciting =>
230							-- wait for sampling to finish
231							START_SAMPLING <= '0';
232							if SAMPLING_BUSY = '0' then
233								RESULT_INDEX <= std_logic_vector(stage_cnt) & std_logic_vector(point_cnt);
234								state <= WaitTriggerLow;
235							end if;
236						when WaitTriggerLow =>
237							NEW_DATA <= '0';
238							if SYNC_MASTER = '1' then
239								TRIGGER_OUT <= '0';
240							end if;
241							if TRIGGER_IN = '0' or SYNC_ENABLED = '0' then
242								TRIGGER_OUT <= '0';
243								state <= SamplingDone;
244							end if;
245						when SamplingDone =>
246							NEW_DATA <= '1';
247							if stage_cnt < unsigned(STAGES) then
248								stage_cnt <= stage_cnt + 1;
249								-- can go directly to preperation for next stage
250								state <= Settling;
251							else
252								state <= NextPoint;
253							end if;
254							settling_cnt <= unsigned(SETTLING_TIME);
255						when NextPoint =>
256							NEW_DATA <= '0';
257							if point_cnt < unsigned(NPOINTS) then
258								point_cnt <= point_cnt + 1;
259								stage_cnt <= (others => '0');
260								state <= TriggerSetup;
261							else 
262								point_cnt <= (others => '0');
263								state <= Done;
264								TRIGGER_OUT <= '0';
265							end if;					
266						when others =>
267					end case;
268				end if;
269			end if;
270		end process;
271	end Behavioral;
272	
