void FPGA::StopSweep() {
	Low(AUX3);
}

void FPGA::StartSweep() {
	StopSweep();
	Delay::us(1);
	High(AUX3);
}

void FPGA::AbortSweep() {
	// abort any FPGA operation by pulling sweep pin low
	StopSweep();
	// data transfer of a datapoint might still be active, abort
	HAL_SPI_DMAStop(&FPGA_SPI);
	busy_reading = false;
}

void FPGA::SetMode(Mode mode) {
	switch(mode) {
	case Mode::FPGA:
		// Both AUX1/2 low
		Low(AUX1);
		Low(AUX2);
		Delay::us(1);
		High(CS);
		// Configure SPI to use faster speed of 42.5MHz
		FPGA_SPI.Instance->CR1 = (FPGA_SPI.Instance->CR1 & ~SPI_CR1_BR_Msk) | SPI_BAUDRATEPRESCALER_4;

